SELECT * FROM adapay_member
WHERE operator_type = #{operatorType}
  AND operator_id = #{operatorId}
  AND company_id = #{companyId}
ORDER BY id DESC
LIMIT 1

SELECT * FROM adapay_settle_account
WHERE member_id = #{memberId}
  AND company_id = #{companyId}
ORDER BY id DESC
LIMIT 1

SELECT * FROM adapay_corp_member
WHERE member_id = #{memberId}
  AND company_id = #{companyId}
ORDER BY id DESC
LIMIT 1

SELECT CONCAT(COALESCE(p.area_name, ''), '-', COALESCE(a.area_name, ''))
FROM adapay_regions p
CROSS JOIN adapay_regions a
WHERE p.area_code = #{provCode}
  AND a.area_code = #{areaCode}
LIMIT 1
